long long solve(int n,const char*coords){
    set<P>s;const char*p=coords;
    for(int i=0;i<n;i++){ll x,y;sscanf(p,"%lld %lld",&x,&y);s.emplace(x,y);while(*p&&*p!='\n')p++;if(*p=='\n')p++;}
