    for(auto&pt:pts){while(h.size()>=2&&cross(h[h.size()-2],h.back(),pt)<=0)h.pop_back();h.push_back(pt);}
    int lo=h.size();
    for(int i=m-2;i>=0;i--){while((int)h.size()>lo&&cross(h[h.size()-2],h.back(),pts[i])<=0)h.pop_back();h.push_back(pts[i]);}
