#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
ll gcd(ll a,ll b){return b?gcd(b,a%b):a;}
int main(){
    ios::sync_with_stdio(false);cin.tie(0);
    int n;cin>>n;
    vector<pair<ll,ll>>pts(n);
    for(auto&p:pts)cin>>p.first>>p.second;
    if(n==1){cout<<1<<"\n";return 0;}
    int best=2;
    for(int i=0;i<n;i++){
        map<pair<ll,ll>,int>slope;
        for(int j=0;j<n;j++){
            if(i==j)continue;
            ll dx=pts[j].first-pts[i].first,dy=pts[j].second-pts[i].second;
            ll g=gcd(abs(dx),abs(dy));if(g==0)g=1;dx/=g;dy/=g;
