    int m=0;long[][]pts=new long[n][2];for(long[]p:all){if(m==0||p[0]!=pts[m-1][0]||p[1]!=pts[m-1][1]){pts[m][0]=p[0];pts[m][1]=p[1];m++;}}
    if(m==1)return 0;
    long[][]h=new long[2*m][2];int k=0;
    for(int i=0;i<m;i++){while(k>=2&&cross(h[k-2],h[k-1],pts[i])<=0)k--;h[k][0]=pts[i][0];h[k][1]=pts[i][1];k++;}
    int lo=k;for(int i=m-2;i>=0;i--){while(k>lo&&cross(h[k-2],h[k-1],pts[i])<=0)k--;h[k][0]=pts[i][0];h[k][1]=pts[i][1];k++;}k--;
    int sz=k;long best=0;int j=1;
    for(int i=0;i<sz;i++){
        boolean go=true;while(go){int ni=(i+1)%sz,nj=(j+1)%sz;long dx=h[nj][0]-h[j][0],dy=h[nj][1]-h[j][1],ex=h[ni][0]-h[i][0],ey=h[ni][1]-h[i][1];if(dx*ey-dy*ex>0)j=nj;else go=false;}
        best=Math.max(best,dist2(h[i],h[j]));
    }
    return best;
}}
